declare(strict_types=1);$active_module='rate_rules';require_once __DIR__.'/layout.php';if(empty($_SESSION['supplier_csrf']))$_SESSION['supplier_csrf']=bin2hex(random_bytes(32));$u=$supplier_user;$pdo=db();$message='';$error='';
try{if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['supplier_csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Güvenlik doğrulaması geçersiz.');$action=$_POST['action']??'';
if($action==='rule'){$property=(int)$_POST['property_id'];$name=trim((string)$_POST['name']);$type=$_POST['rule_type']??'percent';$value=(float)$_POST['value'];if(!$property||$name===''||!in_array($type,['percent','fixed','derived','promo_code','free_night'],true))throw new RuntimeException('Kural bilgilerini kontrol edin.');$pdo->prepare('INSERT INTO rate_rules(supplier_id,property_id,rate_plan_id,name,rule_type,value,currency,booking_start,booking_end,stay_start,stay_end,min_advance_days,markets,nationalities,channels,occupancy_rules,promo_code,priority,stackable) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?::jsonb,?::jsonb,?::jsonb,?::jsonb,?,?,?)')->execute([$u['supplier_id'],$property,(int)$_POST['rate_plan_id']?:null,$name,$type,$value,$_POST['currency']??'EUR',$_POST['booking_start']?:null,$_POST['booking_end']?:null,$_POST['stay_start']?:null,$_POST['stay_end']?:null,max(0,(int)$_POST['min_advance_days']),json_encode(array_filter(array_map('trim',explode(',',$_POST['markets']??'')))),json_encode(array_filter(array_map('trim',explode(',',$_POST['nationalities']??'')))),json_encode(array_filter(array_map('trim',explode(',',$_POST['channels']??'')))),json_encode(['adults'=>(int)($_POST['adults']??0),'children'=>(int)($_POST['children']??0)]),trim((string)$_POST['promo_code'])?:null,(int)$_POST['priority'],isset($_POST['stackable'])]);$message='Fiyat/kontrat kuralı aktifleştirildi.';}
if($action==='restriction'){$room=(int)$_POST['room_type_id'];$rate=(int)$_POST['rate_plan_id'];$from=$_POST['from'];$to=$_POST['to'];if(!$room||!$rate||!$from||!$to||$from>$to)throw new RuntimeException('Oda, fiyat planı ve tarih aralığını kontrol edin.');$rc=$pdo->prepare('SELECT r.property_id FROM room_types r JOIN properties p ON p.id=r.property_id WHERE r.id=? AND p.supplier_id=?');$rc->execute([$room,$u['supplier_id']]);$roomProp=$rc->fetchColumn();$rc=$pdo->prepare('SELECT r.property_id FROM rate_plans r JOIN properties p ON p.id=r.property_id WHERE r.id=? AND p.supplier_id=?');$rc->execute([$rate,$u['supplier_id']]);$rateProp=$rc->fetchColumn();if(!$roomProp||!$rateProp||$roomProp!==$rateProp)throw new RuntimeException('Oda tipi ve fiyat planı aynı ürüne ait olmalıdır.');$q=$pdo->prepare('UPDATE inventory_calendar SET min_stay=?,max_stay=?,closed_to_arrival=?,closed_to_departure=?,min_advance_days=?,max_advance_days=? WHERE room_type_id=? AND rate_plan_id=? AND stay_date BETWEEN ? AND ?');$q->execute([max(1,(int)$_POST['min_stay']),($_POST['max_stay']??'')===''?null:max(1,(int)$_POST['max_stay']),isset($_POST['cta']),isset($_POST['ctd']),max(0,(int)$_POST['min_advance']),($_POST['max_advance']??'')===''?null:max(0,(int)$_POST['max_advance']),$room,$rate,$from,$to]);$message=$q->rowCount().' takvim günü için satış kısıtı kaydedildi.';}}
}catch(Throwable $e){$error=$e->getMessage();}
$q=$pdo->prepare('SELECT p.id,p.name,r.id rate_id,r.name rate_name FROM properties p LEFT JOIN rate_plans r ON r.property_id=p.id AND r.status=\'active\' WHERE p.supplier_id=? ORDER BY p.name,r.name');$q->execute([$u['supplier_id']]);$productRates=$q->fetchAll();$q=$pdo->prepare('SELECT r.*,p.name property_name,rp.name rate_name FROM rate_rules r JOIN properties p ON p.id=r.property_id LEFT JOIN rate_plans rp ON rp.id=r.rate_plan_id WHERE r.supplier_id=? ORDER BY r.priority,r.id DESC');$q->execute([$u['supplier_id']]);$rules=$q->fetchAll();$q=$pdo->prepare('SELECT rt.id,rt.property_id,rt.name,p.name property_name FROM room_types rt JOIN properties p ON p.id=rt.property_id WHERE p.supplier_id=? ORDER BY p.name,rt.name');$q->execute([$u['supplier_id']]);$roomTypes=$q->fetchAll();$rateGroups=[];foreach($productRates as $x){if($x['rate_id'])$rateGroups[$x['id']][]=$x;}
supply_start('Satış kuralları & kontratlar',$active_module);?><section class="page-intro"><p>Fiyat planlarını, kampanyaları, pazar/uyruk hedeflerini ve gelişmiş kalış kısıtlarını tek kural setinde yönetin.</p></section><?php if($message):?><p class="save-success">✓ <?=htmlspecialchars($message)?></p><?php endif;?><?php if($error):?><p class="login-error"><?=htmlspecialchars($error)?></p><?php endif;?><section class="next-module"><h2>Fiyat, kontrat ve kampanya kuralı</h2><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="rule"><div class="form-row"><label>Ürün<select name="property_id"><?php foreach($productRates as $x):?><option value="<?=$x['id']?>"><?=htmlspecialchars($x['name'])?></option><?php endforeach;?></select></label><label>Fiyat planı<select name="rate_plan_id"><option value="">Tüm fiyat planları</option><?php foreach($productRates as $x):if($x['rate_id']):?><option value="<?=$x['rate_id']?>"><?=htmlspecialchars($x['name'].' · '.$x['rate_name'])?></option><?php endif;endforeach;?></select></label><label>Kural adı<input name="name" placeholder="Erken rezervasyon 2027" required></label></div><div class="form-row"><label>Tip<select name="rule_type"><option value="percent">Yüzde indirim/ek</option><option value="fixed">Sabit tutar</option><option value="derived">Ana fiyattan türetilmiş</option><option value="promo_code">Promosyon kodu</option><option value="free_night">Ücretsiz gece</option></select></label><label>Değer<input type="number" name="value" step="0.01" value="0"></label><label>Para birimi<select name="currency"><option>EUR</option><option>TRY</option><option>USD</option><option>GBP</option></select></label><label>Promosyon kodu<input name="promo_code" placeholder="YAZ2027"></label></div><div class="form-row"><label>Satış başlangıç<input type="date" name="booking_start"></label><label>Satış bitiş<input type="date" name="booking_end"></label><label>Konaklama başlangıç<input type="date" name="stay_start"></label><label>Konaklama bitiş<input type="date" name="stay_end"></label></div><div class="form-row"><label>Min. erken rezervasyon günü<input type="number" name="min_advance_days" min="0" value="0"></label><label>Pazarlar (virgülle)<input name="markets" placeholder="TR,DE,GB"></label><label>Uyruklar (virgülle)<input name="nationalities" placeholder="TR,DE"></label><label>Kanallar (virgülle)<input name="channels" placeholder="booking_com,agency"></label></div><label>Öncelik<input type="number" name="priority" value="100"></label><label><input type="checkbox" name="stackable"> Diğer kampanyalarla birleşebilir</label><button>Kuralı aktif et</button></form></section><section class="next-module"><h2>Gelişmiş kalış kısıtları</h2><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="restriction"><div class="form-row"><label>Oda tipi<select name="room_type_id" required><?php foreach($roomTypes as $rt): ?><option value="<?= (int)$rt['id'] ?>"><?= htmlspecialchars($rt['property_name'].' · '.$rt['name']) ?></option><?php endforeach; ?></select></label><label>Fiyat planı<select name="rate_plan_id" required><?php foreach($rateGroups as $plans): ?><optgroup label="<?= htmlspecialchars((string)$plans[0]['name']) ?>"><?php foreach($plans as $plan): ?><option value="<?= (int)$plan['rate_id'] ?>"><?= htmlspecialchars((string)$plan['rate_name']) ?></option><?php endforeach; ?></optgroup><?php endforeach; ?></select></label><label>Başlangıç<input type="date" name="from" required></label><label>Bitiş<input type="date" name="to" required></label></div><div class="form-row"><label>Min. kalış<input type="number" name="min_stay" min="1" value="1"></label><label>Maks. kalış<input type="number" name="max_stay" min="1"></label><label>Min. satış öncesi gün<input type="number" name="min_advance" min="0" value="0"></label><label>Maks. satış öncesi gün<input type="number" name="max_advance" min="0"></label></div><label><input type="checkbox" name="cta"> Girişe kapalı (CTA)</label><label><input type="checkbox" name="ctd"> Çıkışa kapalı (CTD)</label><button>Kısıtları takvime uygula</button></form><p class="page-intro">Oda tipi ve fiyat planı, ürününüzün gerçek envanterinden seçilir; aynı ürüne ait olmayan kombinasyonlar kaydedilmez.</p></section><section class="next-module"><h2>Aktif kurallar</h2><?php foreach($rules as $r):?><p><b><?=htmlspecialchars($r['name'])?></b> · <?=htmlspecialchars($r['property_name'])?> · <?=htmlspecialchars($r['rule_type'])?> <?=htmlspecialchars($r['value'])?> · öncelik <?=htmlspecialchars($r['priority'])?> · <?=htmlspecialchars($r['status'])?></p><?php endforeach;?></section><?php supply_end();
